-- Daily challenges for 2026-11-24: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-11-24. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('asking-good-questions', 'Asking Good Questions', 'For anyone who wants conversations to go deeper than small talk. Each day is one small way to ask a better question, follow up on an answer, and stay curious about the people around you, at home, at work and with new faces.', 'Communication', 365, array['Communication', 'Relationships']::text[], 1, '2026-11-24T17:00:00+00:00'::timestamptz),
  ('enjoying-free-places-near-you', 'Enjoying Free Places Near You', 'For anyone who wants more to do without spending more. Each day is one small way to discover and enjoy the free places around you, from libraries and parks to community centers, free museum hours, trails and town events.', 'Wellbeing', 365, array['Self-Care', 'Loneliness']::text[], 1, '2026-11-24T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('asking-good-questions', 'enjoying-free-places-near-you');

